-- 007: Traducciones al inglés del contenido turístico (requiere la migración 014).
-- Idempotente: se puede ejecutar varias veces. Generado a partir de las fichas en español.
-- Si después se edita un texto en español, actualiza también su traducción en la columna traducciones.
BEGIN;

UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "A natural, partly developed bathing spot (balneario) tucked away among the semi-arid mountains of Peñamiller. Fed by crystal-clear springs, it is a true 'oasis' in the middle of the Sierra Gorda, offering rest and fun for the whole family.", "direccion": "A few kilometres from the municipal seat of Peñamiller. [Google Maps link]", "info_acceso": "Reachable by paved road plus a short stretch of dirt road in good condition. Located near the riverbed.", "horarios": "Tuesday to Sunday, 9:00 a.m.–6:00 p.m. (subject to change).", "costo": "Approximate general admission: $70 - $100 MXN.", "actividades": "Swimming in pools, camping, family gatherings, picnics.", "servicios_disponibles": "Family pools and wading pools, barbecue grills, restrooms, showers, green areas and a camping area.", "accesibilidad": "Flat areas with concrete walkways, accessible for people with reduced mobility (as far as the pool area).", "recomendaciones": "Bring biodegradable sunscreen; glass containers are not allowed. It tends to be crowded on weekends.", "contacto": "El Oasis local management."}$tr$::jsonb) WHERE slug = 'balneario-el-oasis';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "A spectacular natural gorge flanked by immense walls of black marble. The Extoraz River runs through it, making it a mystical and challenging landscape, ideal for lovers of adventure tourism and extreme hiking.", "direccion": "Community of Río Blanco, Peñamiller. [Google Maps link]", "info_acceso": "You can drive as far as the community of Río Blanco; from there you must hike along the bed of the Extoraz River (river trekking).", "horarios": "Tours run from sunrise until mid-afternoon to avoid being in the canyon after dark.", "costo": "Free access, but hiring a local guide is strongly recommended (approx. $200-$400 MXN).", "actividades": "River trekking (walking along the river), canyoning, landscape photography and geological observation.", "servicios_disponibles": "None in the canyon. The community of Río Blanco has basic shops.", "accesibilidad": "Very difficult. Requires walking over river stones, crossing streams and climbing rocks. Not suitable for wheelchairs or very young children.", "recomendaciones": "Life jackets are mandatory (in the pools); wear water shoes or sneakers with good grip. DO NOT visit during the heavy rainy season due to the risk of flash floods.", "contacto": "Community guides from Río Blanco."}$tr$::jsonb) WHERE slug = 'canon-del-paraiso';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "An impressive waterfall surrounded by the humid, wooded landscape typical of the gateway to the Sierra Gorda. Ideal for disconnecting and enjoying nature at its purest.", "direccion": "About 20 minutes from the municipal seat of San Joaquín. [Google Maps link]", "info_acceso": "From the main square of San Joaquín, take a dirt road towards the wooded area. A high-clearance vehicle or ATV is recommended, followed by a downhill walk.", "horarios": "8:00 a.m.–5:00 p.m. (recommended during daylight).", "costo": "Approximately $50 MXN (community fee).", "actividades": "Hiking, landscape photography, picnics, ecotourism.", "servicios_disponibles": "Rustic, basic services run by the local community (palapas — thatched shelters — and occasional food sales in high season).", "accesibilidad": "Low accessibility. The trail is dirt with steep slopes and stones. Not suitable for wheelchairs or people with reduced mobility.", "recomendaciones": "Wear footwear with good (non-slip) grip; bring drinking water and eco-friendly insect repellent. Avoid swimming when currents are strong.", "contacto": "San Joaquín local community."}$tr$::jsonb) WHERE slug = 'cascadas-maravilla';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "One of the highest and most spectacular points in the Sierra Gorda. Famous for its panoramic view where the semi-desert meets the oak forests, and for the 'sea of clouds' phenomenon at sunrise.", "direccion": "At the top of Cerro de la Media Luna, community of Cuatro Palos. [Google Maps link]", "info_acceso": "Turn off at the community of La Cañada (Highway 120) and drive up a dirt road of approx. 5 km. A high-clearance vehicle or hiring local transport is recommended.", "horarios": "6:00 a.m.–6:00 p.m. (ideally arrive at sunrise).", "costo": "Approx. admission: $80 - $100 MXN.", "actividades": "Scenery viewing, sunrise photography, hiking, camping.", "servicios_disponibles": "Community guides (mandatory to access the viewpoint), camping area, rustic restrooms, antojitos (Mexican snacks) sold on weekends.", "accesibilidad": "Medium difficulty. Uphill walk along a dirt trail and stone steps. Not suitable for wheelchairs.", "recomendaciones": "Bring very warm clothing (it is very cold before dawn) and mountain footwear. Do not go up during a storm.", "contacto": "Cuatro Palos Tourism Committee."}$tr$::jsonb) WHERE slug = 'cuatro-palos';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "A splendid waterfall almost 30 metres high, surrounded by a lush forest of poplars, willows and ferns. Its crystal-clear waters flow on to form natural pools.", "direccion": "A few kilometres from the municipal seat, on the way to Jalpan. [Google Maps link]", "info_acceso": "On Highway 120 (San Juan del Río-Xilitla), about 18 km from Pinal de Amoles, take the signposted turnoff and go down the dirt road to the parking lot.", "horarios": "Monday to Sunday, 8:00 a.m.–5:00 p.m.", "costo": "General admission: approx. $80 MXN.", "actividades": "Easy hiking, photography, wildlife and plant observation, picnics.", "servicios_disponibles": "Parking, restrooms, regional food stalls (weekends), regulated camping area.", "accesibilidad": "Flat, tree-lined dirt trail of about 15-20 minutes from the parking lot. Accessible for most people, though difficult for wheelchairs in the rainy season because of mud.", "recomendaciones": "SWIMMING IS PROHIBITED (it is a nature reserve protecting endemic wildlife such as the axolotl). Alcoholic beverages and pets are not allowed.", "contacto": "CONANP / El Chuveje management."}$tr$::jsonb) WHERE slug = 'el-chuveje';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "Spectacular ancient caverns fitted out for visitors, where you can admire impressive stalactite and stalagmite formations that nature has sculpted over thousands of years.", "direccion": "Just 10 minutes from the municipal seat of San Joaquín. [Google Maps link]", "info_acceso": "Paved access very close to downtown San Joaquín. There are clear signs along the main road.", "horarios": "Tuesday to Sunday, 10:00 a.m.–5:00 p.m.", "costo": "General admission: $40 - $50 MXN.", "actividades": "Cave exploration, geological photography, family tourism.", "servicios_disponibles": "Parking, restrooms, lit concrete walkways and stairways with handrails inside the cave.", "accesibilidad": "The interior is fitted with stairs and secure railings, but it is not wheelchair accessible due to the cave's natural changes in level.", "recomendaciones": "Wear comfortable, closed-toe shoes. Do not touch the rock formations, to avoid damaging their natural growth.", "contacto": "Municipal tourism management."}$tr$::jsonb) WHERE slug = 'grutas-de-los-herrera';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "The spot where the warm, transparent waters of the Río Santa María meet the cold, blue-toned waters of the Río Ayutla, creating an ideal temperature and a spectacular view.", "direccion": "Approximate coordinates: 21.3934, -99.5852. Google Maps link pending. Access point in the community of Ayutla.", "info_acceso": "From the municipal seat of Arroyo Seco, take the main road towards Jalpan and turn off at Ayutla. The final stretch is a dirt road; a high-clearance vehicle or walking is recommended.", "horarios": "Open every day. Daylight visits are recommended (8:00 a.m.–6:00 p.m.).", "costo": "General admission is free, but the ejidatarios (communal landholders) may charge a maintenance fee of $30 to $50 MXN per vehicle or campsite.", "actividades": "Swimming, camping, hiking, photography and wildlife/plant observation.", "servicios_disponibles": "Rustic parking, barbecue grills and cabins for rent nearby in the community of Ayutla.", "accesibilidad": "Difficult access for people with reduced mobility due to the uneven dirt terrain and river stones.", "recomendaciones": "Bring eco-friendly repellent and water shoes; do not leave litter. During the heavy rainy season the river flow can be dangerous.", "contacto": "There is no central management; contact service providers in Ayutla."}$tr$::jsonb) WHERE slug = 'las-adjuntas';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "A recent tourist attraction consisting of a transparent glass platform suspended more than 120 metres above a cliff, offering dizzying views of the canyon and the green sierra.", "direccion": "Near Puerta del Cielo and the municipal seat. [Google Maps link]", "info_acceso": "Access from main Highway 120, just minutes from downtown Pinal de Amoles.", "horarios": "Monday to Sunday, 9:00 a.m.–6:00 p.m. (weather permitting).", "costo": "Approx. admission: $150 MXN (includes use of the glass viewpoint for a limited time).", "actividades": "Adventure photography, enjoying the scenery.", "servicios_disponibles": "On-site photographer (optional, extra charge), restrooms, zip line (at some nearby complexes).", "accesibilidad": "Accessible via wooden and metal stairs. Shoes are not allowed on the platform (shoe covers are provided to protect the glass).", "recomendaciones": "Not suitable for people with an extreme fear of heights. Follow the instructions on maximum time allowed on the platform.", "contacto": "Pinal de Amoles Municipal Tourism Office."}$tr$::jsonb) WHERE slug = 'mirador-de-cristal';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "It was the first of the five Franciscan missions built under the direction of Fray Junípero Serra in the Sierra Gorda (built between 1751 and 1758). It stands out for its stucco façade in the mestizo Baroque style, where European elements blend with Indigenous flora and symbols.", "direccion": "Opposite the main square of Jalpan de Serra.", "info_acceso": "Located in the heart of the municipal seat, on the Plaza Principal (main square); easily reached on foot or by vehicle.", "horarios": "9:00 a.m.–6:00 p.m. every day.", "costo": "Free admission.", "actividades": "Cultural and religious tourism, architectural photography.", "servicios_disponibles": "Shops, restaurants and public restrooms available around the main square.", "accesibilidad": "Highly accessible. The atrium and main nave are at street level, suitable for people with reduced mobility.", "recomendaciones": "Look at the details of the façade at sunset to appreciate the relief.", "contacto": "Parroquia de Santiago Apóstol (parish)."}$tr$::jsonb) WHERE slug = 'mision-de-jalpan';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "Built between 1761 and 1764, it is considered the mission with the most ornate and theologically profound façade. Dedicated to the Purísima Concepción (Immaculate Conception), it represents the City of God and was the missionary starting point for Texas and California.", "direccion": "Historic Center of Landa de Matamoros. [Google Maps link]", "info_acceso": "Reachable via Federal Highway 120 (San Juan del Río - Xilitla). It is on the town's main square, 20 km from Jalpan.", "horarios": "Monday to Sunday, 8:00 a.m.–6:00 p.m.", "costo": "Free admission.", "actividades": "Religious and cultural tourism, historic architecture and photography.", "servicios_disponibles": "Food, ATMs and small shops around the square.", "accesibilidad": "Paved, street-level access.", "recomendaciones": "Please keep quiet indoors and do not use flash photography.", "contacto": "Landa local parish."}$tr$::jsonb) WHERE slug = 'mision-de-landa';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "It is the smallest of the five missions of the Sierra Gorda and the first to be completed (1754). It is notable for the double-headed eagle (a Habsburg symbol) and Indigenous details such as flowers, foliage and animals.", "direccion": "Opposite the main square of Concá. Google Maps link pending.", "info_acceso": "Reachable by paved road (Federal Highway 69, Jalpan - Río Verde).", "horarios": "Open during the day for visits; Mass is held on Sundays and holidays.", "costo": "Free admission.", "actividades": "Religious, cultural and architectural tourism, and photography.", "servicios_disponibles": "The village has shops, public restrooms and places to eat.", "accesibilidad": "Accessible at the entrance; some interior areas may have changes in level.", "recomendaciones": "Be respectful; do not use flash inside.", "contacto": "Concá local parish."}$tr$::jsonb) WHERE slug = 'mision-de-san-miguel-conca';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "A Franciscan mission distinguished by having the most iconographically elaborate façade of the five missions, dedicated to Nuestra Señora de la Luz (Our Lady of Light). It was built by Pame communities under Franciscan supervision.", "direccion": "Community of Tancoyol, Jalpan de Serra.", "info_acceso": "45 minutes northeast of Jalpan de Serra, taking the turnoff from Highway 120 towards Tancoyol.", "horarios": "9:00 a.m.–5:00 p.m. every day.", "costo": "Free admission.", "actividades": "Cultural and religious tourism, photography.", "servicios_disponibles": "Basic services in the small community of Tancoyol.", "accesibilidad": "Wheelchair accessible as far as the atrium; low steps at the main entrance.", "recomendaciones": "Fill up on gas in Jalpan before taking the turnoff, as there are fewer services along the route.", "contacto": "Diocese of Querétaro."}$tr$::jsonb) WHERE slug = 'mision-de-tancoyol';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "It is the smallest mission, but its naive, cheerful ornamentation includes mermaids, an unusual element in sacred art. Built between 1754 and 1762 in a small valley surrounded by mountains.", "direccion": "Community of Tilaco, Landa de Matamoros. [Google Maps link]", "info_acceso": "From Landa, continue along Federal Highway 120 and take the paved turnoff towards Tilaco (approx. 30 minutes).", "horarios": "Monday to Sunday, 9:00 a.m.–5:00 p.m.", "costo": "Free admission.", "actividades": "Cultural and architectural tourism.", "servicios_disponibles": "Family-run fondas (small eateries), small local inns.", "accesibilidad": "Ramp at the entrance and a flat square; however, the side entrances may have changes in level.", "recomendaciones": "Best visited during the day to better appreciate the valley and the architectural details.", "contacto": "Community office (delegación)."}$tr$::jsonb) WHERE slug = 'mision-de-tilaco';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "It is the easternmost point of the state of Querétaro, known for its cloud forests, coffee plantations and its proximity to the Moctezuma River. Highlights include the Cascada de Neblinas (Neblinas Waterfall) and its lush biodiversity.", "direccion": "Community of Neblinas, east of Landa de Matamoros. [Google Maps link]", "info_acceso": "The road is a winding dirt road. A 4x4 vehicle or high-clearance pickup is recommended. From Highway 120, take the turnoff at La Lagunita.", "horarios": "Open 24 hours, but travel in daylight is required.", "costo": "Generally free; token ejido (communal land) fees.", "actividades": "Hiking, camping, landscape photography, experiencing rural life.", "servicios_disponibles": "Very basic services in the community (grocery stores and very limited rustic lodging).", "accesibilidad": "High difficulty; dirt roads become slippery in the rainy season. Not suitable for people with reduced mobility.", "recomendaciones": "Travel in the dry season, bring supplies and ask about local guides.", "contacto": "Neblinas ejido (communal land) authorities."}$tr$::jsonb) WHERE slug = 'neblinas';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "An artificial oasis that has blended perfectly into the Sierra Gorda ecosystem. It was declared a Ramsar site (wetland of international importance) because of the large number of migratory birds it receives.", "direccion": "1.5 km south of the main square of Jalpan.", "info_acceso": "You can walk from downtown Jalpan along the tree-lined promenade, or drive there in 5 minutes.", "horarios": "Public space open 24 hours (recommended hours: 7:00 a.m.–7:00 p.m.).", "costo": "Free access.", "actividades": "Boat rides, kayaking, sport fishing, mountain biking (circuit around the reservoir), birdwatching.", "servicios_disponibles": "Kayak rental, palapas (thatched shelters), barbecue grills, bike rental, nearby eco-tourism cabins.", "accesibilidad": "High along the main promenade and palapa areas. Low on the unpaved perimeter trails.", "recomendaciones": "Bring binoculars for birdwatching. Wear a life jacket for water activities.", "contacto": "Jalpan de Serra Municipal Tourism Office."}$tr$::jsonb) WHERE slug = 'presa-jalpan';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "An important ceremonial, political and religious center associated with pre-Hispanic mining (especially of cinnabar) during the Classic period. Its structures are strategically built on natural elevations using stone slabs.", "direccion": "3 km north of the municipal seat of San Joaquín. [Google Maps link]", "info_acceso": "Paved road from downtown San Joaquín; you can get there by vehicle or on foot in about 45 minutes.", "horarios": "Wednesday to Sunday, 9:00 a.m.–5:00 p.m.", "costo": "Mexican visitors: $80 MXN. Foreign visitors: $145 MXN.", "actividades": "Archaeological tourism, photography, learning about the cultures of the Sierra Gorda, viewing the ball courts.", "servicios_disponibles": "INAH (National Institute of Anthropology and History) custodians, ticket office, restrooms at the entrance, information signage.", "accesibilidad": "Uneven terrain with dirt trails and pre-Hispanic stairways. Difficult for people with reduced mobility.", "recomendaciones": "Bring a hat, sunscreen and water. Respect the marked boundaries and do not climb restricted structures.", "contacto": "INAH Querétaro."}$tr$::jsonb) WHERE slug = 'ranas';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "A beautiful waterfall surrounded by low tropical forest and woodland vegetation. Its clean, crystal-clear waters form natural pools in emerald-green tones.", "direccion": "Community of Río Verdito, Landa de Matamoros. [Google Maps link]", "info_acceso": "From the main highway (120), take the turnoff towards Agua Zarca and then towards Río Verdito. Paved road up to the village, followed by a footpath.", "horarios": "Daylight hours (7:00 a.m.–6:00 p.m.).", "costo": "Community contribution of $20 to $50 MXN.", "actividades": "Swimming, hiking, ecotourism and picnics.", "servicios_disponibles": "Eateries serving traditional food, rustic restrooms and camping areas (run by the community).", "accesibilidad": "The trail to the waterfall includes stone steps and slippery slopes; not suitable for wheelchairs.", "recomendaciones": "Bring eco-friendly repellent, water shoes and trash bags.", "contacto": "Río Verdito tourism committee."}$tr$::jsonb) WHERE slug = 'rio-verdito';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "One of the largest sinkholes (vertical caves) in the world, 410 metres deep and 500 metres in diameter. It is the main home and refuge of the military macaw (guacamaya verde), an endangered species.", "direccion": "Located in the mountains, a 2-hour walk from the community of Santa María de los Cocos.", "info_acceso": "Drive to Santa María de los Cocos; from there, a guided uphill hike begins (approx. 1.5 to 2 hours).", "horarios": "The hike must start before dawn (approx. 4:00 am) to watch the macaws emerge at sunrise.", "costo": "Payment goes to authorized local community guides. Prices vary.", "actividades": "Mountain hiking, birdwatching (military macaw), scenery viewing.", "servicios_disponibles": "No services at the top. Food and parking are available in the base community.", "accesibilidad": "Only for people in good physical condition. NOT wheelchair accessible.", "recomendaciones": "Bring a headlamp, warm clothing, water and hiking boots. Shouting or making noise at the edge of the sinkhole is prohibited.", "contacto": "Community cooperative of Santa María de los Cocos."}$tr$::jsonb) WHERE slug = 'sotano-del-barro';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "A settlement of the Huastec culture whose name means 'Cerro de fuego' (Hill of Fire). It stands out for its adaptation to the mountain topography, with terraced plazas (El Mirador, Santiago, La Promesa) and architecture featuring circular platforms.", "direccion": "About 30 minutes from the municipal seat of Jalpan. [Google Maps link]", "info_acceso": "From Jalpan, take Federal Highway 120 towards Xilitla and then the signposted paved turnoff to Tancama.", "horarios": "Tuesday to Sunday, 9:00 a.m.–4:00 p.m.", "costo": "Approx. $75 MXN (exempt: minors, students and INAPAM senior citizen cardholders).", "actividades": "Archaeological tourism, viewing the platforms, photography of the mountain landscape.", "servicios_disponibles": "INAH custodians, ticket office, restrooms, signage.", "accesibilidad": "Low wheelchair accessibility due to natural terrain and terraced platforms.", "recomendaciones": "Bring water and sunscreen. Stay on the marked trails.", "contacto": "INAH Centro Querétaro."}$tr$::jsonb) WHERE slug = 'tancama';
UPDATE public.lugares_turisticos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "The semi-arid area of Peñamiller is home to ancient traces of human activity. Highlights include remains of old settlements of local cultures and rock paintings that show the region's importance as a pre-Hispanic transit route.", "direccion": "Hills surrounding the municipal seat. (Areas not fully set up for tourism.) [Google Maps link]", "info_acceso": "Depends on the specific area. Generally requires a hike from the municipal seat or nearby communities, guided by locals.", "horarios": "To be arranged with local guides.", "costo": "Local guide fee (variable).", "actividades": "Historical hiking, cultural and archaeological exploration.", "servicios_disponibles": "No services at the archaeological sites; all services are in downtown Peñamiller.", "accesibilidad": "Cross-country climbs or uneven trails. Not suitable for people with reduced mobility.", "recomendaciones": "Hiring a local guide who knows the trails is mandatory. Touching or damaging the paintings and remains is prohibited.", "contacto": "Peñamiller Tourism Office."}$tr$::jsonb) WHERE slug = 'vestigios-prehistoricos';

UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "Rustic but comfortable cabins on the shore of the Presa de Jalpan (Jalpan Reservoir). Kayaks, pedal boats and mountain bikes are available for rent to explore the wetland boardwalks.", "rango_precio": "Cabins from $1,200 MXN per night. Bike and kayak rental approx. $100 - $150 MXN per hour.", "horario": "Office open 09:00 to 18:00. Lodging 24 hours.", "tipo_servicio": "Lodging (Cabins) / Boat and bike rental", "ubicacion": "Carretera Jalpan - Río Verde s/n, on the shore of the Presa Jalpan.", "reservacion": "Book 1 week in advance in low season and 1 month in advance in high season.", "capacidad_requisitos": "Family groups of up to 6 people per cabin.", "accesibilidad": "Rustic dirt-road access; some areas may be difficult for wheelchairs.", "contacto": "Ask at the tourist information booth or directly at the reservoir."}$tr$::jsonb) WHERE slug = 'cabanas-centro-ecoturistico-presa-jalpan';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "Lodging in rustic cabins and campsite rental on the bank of the Extoraz River, within the grounds of the natural swimming spot (balneario). Ideal for relaxation and ecotourism.", "rango_precio": "Cabins from $800 MXN to $1,500 MXN per night. Camping: $150 MXN per tent.", "horario": "Open 24 hours for guests. Arrival recommended before 18:00.", "tipo_servicio": "Lodging (Cabins and Camping)", "ubicacion": "Adjuntas de Higueras community, 15 km from the municipal seat.", "reservacion": "By message to the Facebook page 'Eloasis Semidesierto' or by WhatsApp at least 1 week in advance.", "capacidad_requisitos": "Double or family cabins for up to 8 people.", "accesibilidad": "Accessible up to the camping area and some ground-floor cabins.", "contacto": "WhatsApp: +52 441 292 9000 (approximate / via their official Facebook page)"}$tr$::jsonb) WHERE slug = 'campamento-y-cabanas-el-oasis';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "Spectacular wooded area full of pines and oaks, equipped with palapas (thatched shelters), grills, showers and rustic cabins. Ideal for a getaway from the city, a carne asada (barbecue) and an overnight stay in the mountains.", "rango_precio": "General admission: $20 MXN. Camping fee: $100 - $150 MXN per tent. Cabins from $800 MXN.", "horario": "Daily entry from 08:00 to 18:00. Camping area open 24 hours for guests.", "tipo_servicio": "Lodging (Cabins and Camping)", "ubicacion": "5 minutes from downtown San Joaquín, on the road to the Ranas Archaeological Zone.", "reservacion": "No prior reservation needed for camping, except during the Concurso Nacional de Huapango (National Huapango Contest, April). For cabins, call 15 days in advance.", "capacidad_requisitos": "Large capacity for hundreds of campers. Family cabins for 4 to 10 people.", "accesibilidad": "Accessible for vehicles and wheelchairs in the main grill areas, although the forest trails are uneven.", "contacto": "Municipal Tourism phone: (441) 293 5022"}$tr$::jsonb) WHERE slug = 'campamento-y-zona-ecologica-campo-alegre';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "A space dedicated to the display and sale of regional products: polychrome pottery, embroidered textiles, basketry, honey, fruit liqueurs, mountain-grown coffee and leatherwork made by local communities.", "rango_precio": "Products from $50 MXN (souvenirs) up to $2,000+ MXN (large ceramic pieces).", "horario": "Monday to Sunday, 10:00 to 19:00.", "tipo_servicio": "Crafts and Local Products Shop", "ubicacion": "Next to the main square and inside the arcades (portales) of the historic center.", "reservacion": "No appointment needed; free entry.", "capacidad_requisitos": "Open to the general public.", "accesibilidad": "Level wheelchair access in most of the shops located downtown.", "contacto": "Direct sales in the shop."}$tr$::jsonb) WHERE slug = 'casa-de-las-artesanias-talleres-locales';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "Dining service offering local dishes such as pork in green salsa with nopales (cactus pads), enchiladas queretanas and barbacoa de borrego (slow-cooked lamb), accompanied by the municipality's signature drink: artisanal apple liqueur.", "rango_precio": "Full meals from $80 to $150 MXN. Bottles of apple liqueur from $120 MXN.", "horario": "08:00 to 18:00. Artisanal liqueur shops open 10:00 to 19:00.", "tipo_servicio": "Food and Local Products", "ubicacion": "Mercado Municipal de San Joaquín and restaurants around the Plaza Principal.", "reservacion": "No reservation required.", "capacidad_requisitos": "Many tables in the municipal market and downtown restaurants.", "accesibilidad": "Downtown streets and the market have ramps for pedestrian access.", "contacto": "Walk-in service at shops in the town center."}$tr$::jsonb) WHERE slug = 'fondas-tradicionales-y-productores-de-licor';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "Expert guiding service to safely travel along the Extoraz riverbed and explore deep between the imposing marble walls of the Cañón del Paraíso. They provide basic equipment and advice.", "rango_precio": "From $150 to $300 MXN per person, or group rates by arrangement.", "horario": "Tours from 07:00 until 15:00 (to avoid nightfall in the canyon).", "tipo_servicio": "Tour Guide / Canyoneering", "ubicacion": "Río Blanco community, entrance to the Cañón del Paraíso.", "reservacion": "It is suggested to contact them 1 or 2 days ahead, especially in high season or on weekends.", "capacidad_requisitos": "Groups of 2 to 15 people per guide.", "accesibilidad": "Not wheelchair accessible; requires physical effort, river crossings and walking over rocks.", "contacto": "Contact on arrival in the community or through the Municipal Tourism Office (Tel: 442 406 7956 / 442 120 5652)."}$tr$::jsonb) WHERE slug = 'guias-locales-comunitarios-rio-blanco';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "Hotel with former-hacienda-style architecture. It offers comfortable rooms, a swimming pool, spacious gardens and a restaurant serving regional cuisine.", "rango_precio": "From $1,500 MXN to $2,500 MXN per night.", "horario": "24-hour reception. Restaurant open 07:00 to 22:00.", "tipo_servicio": "Lodging, Restaurant and Events", "ubicacion": "Carretera Jalpan-Río Verde Km 32, C.P. 76340, Concá, Qro.", "reservacion": "Booking through their website or by phone is suggested.", "capacidad_requisitos": "A variety of rooms (single, double and family suites).", "accesibilidad": "Ramps in common areas and ground-floor rooms."}$tr$::jsonb) WHERE slug = 'hotel-hacienda-mision-conca';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "Colonial-style hotel located right across from the main Mission. It offers comfortable rooms, an outdoor pool, and a restaurant serving typical regional cuisine.", "rango_precio": "From $1,800 MXN up to $3,000 MXN per night depending on the season.", "horario": "24-hour reception.", "tipo_servicio": "Lodging, Restaurant", "ubicacion": "Av. Fray Junípero Serra 3, Centro, 76340 Jalpan de Serra, Qro.", "reservacion": "Via website or by phone; standard 48-hour cancellation policy.", "capacidad_requisitos": "Rooms for 2 to 4 people. Has event areas.", "accesibilidad": "Ramps on the first floor and wheelchair access to the restaurant."}$tr$::jsonb) WHERE slug = 'hotel-mision-jalpan';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "Centrally located hotel across from the Mission. It offers family rooms with air conditioning, Wi-Fi and views of the square, making it one of the most comfortable options right in the center of Landa.", "rango_precio": "Rooms from $900 MXN to $1,500 MXN per night.", "horario": "Reception during daytime hours.", "tipo_servicio": "Lodging", "ubicacion": "Across from the main square, Centro, Landa de Matamoros.", "reservacion": "Through online platforms (Airbnb/Booking).", "capacidad_requisitos": "Rooms for 2 to 4 people.", "accesibilidad": "Multi-story building with stair access.", "contacto": "Airbnb or Booking (Hotel Plaza Landa)"}$tr$::jsonb) WHERE slug = 'hotel-plaza-landa';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "One of the most popular and highly rated places to eat among locals in Landa de Matamoros. They serve roast chicken, traditional dishes, gorditas (stuffed corn cakes) and Mexican antojitos (snacks), ideal for refueling after a day of exploring.", "rango_precio": "Average spend of $100 to $150 MXN per person.", "horario": "Monday to Sunday, from midday until the afternoon/evening.", "tipo_servicio": "Food (Local Eatery)", "ubicacion": "Downtown area, Landa de Matamoros.", "reservacion": "No reservation required.", "capacidad_requisitos": "Shared tables for small groups.", "accesibilidad": "Street-level access.", "contacto": "Order at the counter."}$tr$::jsonb) WHERE slug = 'pollos-brandon-comedores-de-landa';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "Guided tours along dirt roads and forest trails. It is the most popular and exciting way to reach hard-to-access spots such as the Cascadas Maravillas or the municipality's high lookout points.", "rango_precio": "Approximately $400 - $600 MXN per hour of touring (2 people per ATV).", "horario": "09:00 to 16:00. Subject to weather conditions (no operation in heavy rain).", "tipo_servicio": "Tourist Transportation / Adventure Sports", "ubicacion": "Departures from the Plaza Principal of San Joaquín or tourist information booths.", "reservacion": "Can be booked on the spot, but on long weekends it is recommended to contact the Municipal Tourism Office (Turismo Municipal) to ensure availability.", "capacidad_requisitos": "Guided groups of up to 10 ATVs (20 people). Minimum age to drive: 18, with a driver's license.", "accesibilidad": "Extreme adventure activity. Not suitable for people with back problems or reduced mobility due to the impact on dirt roads.", "contacto": "Tourist Information Booth on the Main Square."}$tr$::jsonb) WHERE slug = 'renta-y-tours-en-cuatrimoto-san-joaquin-ecotours';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "Traditional restaurant in Arroyo Seco. It offers typical regional dishes.", "rango_precio": "Average spend of $120 to $250 MXN per person.", "horario": "Monday to Sunday, 08:00 to 19:00.", "tipo_servicio": "Food (À la carte restaurant and set-menu meals)", "ubicacion": "Downtown commercial area of Arroyo Seco.", "reservacion": "No prior reservation required.", "capacidad_requisitos": "Dining room with capacity for approximately 30 to 40 people.", "accesibilidad": "Street-level access."}$tr$::jsonb) WHERE slug = 'restaurante-coral';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "A showcase of the area's traditional cuisine, including cecina serrana (mountain-style cured beef), enchiladas huastecas and queretanas, gorditas de maíz quebrado (cracked-corn gorditas) and bocoles (thick corn cakes).", "rango_precio": "Average spend of $150 to $250 MXN per person.", "horario": "Monday to Sunday, 08:00 to 20:00.", "tipo_servicio": "Food (Regional restaurant)", "ubicacion": "Portales area and Historic Center of Jalpan.", "reservacion": "No reservation required.", "capacidad_requisitos": "Dining rooms with tables for 4 to 8 people.", "accesibilidad": "Easy access from the paved main square.", "contacto": "N/A (most fondas don't take reservations)."}$tr$::jsonb) WHERE slug = 'restaurantes-tradicionales-del-centro-especialidad-cecina-serrana';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "Regional eateries serving the area's star dish: 'El Chivo Tapeado' (milk-fed kid goat prepared with dried chiles and baked in a clay pot), as well as gorditas, nopales con pipián (cactus pads in pumpkin-seed sauce) and atole de teja (a warm corn drink).", "rango_precio": "Dishes from $100 to $250 MXN.", "horario": "Every day, 08:00 to 19:00. Chivo tapeado is usually prepared mainly on weekends or by order.", "tipo_servicio": "Food (Restaurant / Fonda)", "ubicacion": "Around the Plaza Principal and market of Peñamiller.", "reservacion": "For large groups, or to guarantee 'Chivo Tapeado' on a weekday, an advance order is required.", "capacidad_requisitos": "Family tables (up to 30 people depending on the establishment).", "accesibilidad": "Level access at the fondas in the historic center.", "contacto": "Walk-in service at each establishment."}$tr$::jsonb) WHERE slug = 'restaurantes-tradicionales-y-fondas-penamiller';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "Official community-based tour operator. It offers guided tours of the Franciscan missions, pottery workshops, nature walks, birdwatching and all-inclusive packages with transportation and meals.", "rango_precio": "Tours from $400 MXN up to multi-day packages of $4,000+ MXN per person.", "horario": "Offices: Monday to Saturday, 09:00 to 18:00.", "tipo_servicio": "Tour Guides and Eco-Tour Operator", "ubicacion": "Centro de Información Turística, Juárez s/n, Centro, Jalpan de Serra.", "reservacion": "Advance reservation online or by phone is required to ensure guide availability.", "capacidad_requisitos": "They serve everyone from solo travelers to large groups (buses).", "accesibilidad": "The offices are accessible; tour accessibility depends on the package chosen."}$tr$::jsonb) WHERE slug = 'sierra-gorda-ecotours-operadora-de-grupo-ecologico-sierra-gorda';
UPDATE public.servicios SET traducciones = jsonb_set(traducciones, '{en}', $tr${"descripcion": "A complex of tourist villas surrounded by nature. Ideal for family trips and groups.", "rango_precio": "From $1,200 MXN per night (basic cabin).", "horario": "Office hours 09:00 to 18:00.", "tipo_servicio": "Lodging (Villas and Cabins)", "ubicacion": "Main road of Arroyo Seco, C.P. 76430.", "reservacion": "By direct contact via WhatsApp.", "capacidad_requisitos": "Villas suited for groups of 4 to 12 people.", "accesibilidad": "Rustic access; limited wheelchair access in the gardens.", "contacto": "Ask in person or at the municipal tourism offices."}$tr$::jsonb) WHERE slug = 'villas-villa-riviera';

UPDATE public.eventos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"nombre": "Day of the Dead in the Sierra Gorda", "descripcion": "Altars, offerings (ofrendas) and arches of cempasúchil (marigold) flowers in the region's plazas and cemeteries. One of the most vibrant traditions of the mountain communities, with families visiting their departed loved ones and traditional food.", "horario": "All day; the offerings look best in the late afternoon and evening."}$tr$::jsonb) WHERE nombre = 'Día de Muertos en la Sierra Gorda';
UPDATE public.eventos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"nombre": "Feast of the Immaculate Conception at the Landa Mission", "descripcion": "Patron saint festival of the Franciscan mission of Santa María de la Purísima Concepción del Agua de Landa, a World Heritage Site. Religious celebration with a procession, traditional music and a fair in the plaza.", "horario": "Main day: December 8."}$tr$::jsonb) WHERE nombre = 'Fiesta de la Purísima Concepción en la Misión de Landa';
UPDATE public.eventos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"nombre": "National Huapango Contest in San Joaquín", "descripcion": "A gathering of huapango dance couples from across the country, accompanied by tríos huastecos (Huastec string trios). It is San Joaquín's most iconic event and is traditionally held during Holy Week (Semana Santa).", "horario": "Holy Week (dates to be confirmed in the official announcement)."}$tr$::jsonb) WHERE nombre = 'Concurso Nacional de Huapango en San Joaquín';
UPDATE public.eventos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"nombre": "Feast of Saint James the Apostle in Jalpan de Serra", "descripcion": "Patron saint festival of the Misión de Santiago de Jalpan, the first of the five Franciscan missions founded by Fray Junípero Serra. Includes religious celebrations, dances, huapango and a fair.", "horario": "Main day: July 25."}$tr$::jsonb) WHERE nombre = 'Fiesta de Santiago Apóstol en Jalpan de Serra';
UPDATE public.eventos SET traducciones = jsonb_set(traducciones, '{en}', $tr${"nombre": "Feast of Saint Michael the Archangel in Concá", "descripcion": "Patron saint festival of the Misión de San Miguel Concá, in Arroyo Seco. The community celebrates with Mass, a procession, huapango music and local food.", "horario": "Main day: September 29."}$tr$::jsonb) WHERE nombre = 'Fiesta de San Miguel Arcángel en Concá';

