UPDATE public.promociones SET traducciones = jsonb_set(traducciones, '{en}', $tr${"titulo": "Day of the Dead season: extra night", "descripcion": "Lodging in the Sierra Gorda with an additional night at a special price during the Day of the Dead season.", "condiciones": "XploraSG prototype demo promotion. Applies to stays of 2 nights or more."}$tr$::jsonb) WHERE titulo = 'Temporada de Día de Muertos: noche extra';
